// === Tab: mySketch ===
//for the #wccChallenge on the theme of "Biomes" 
//A field of particles moving through 3D space that absorb each other on contact
//Particles grow as they absorb other particles and on reaching a certain size will 'explode'
//leaving behind a scattering of new particles that inherit it's color and shape traits
//(with a small amount of 'mutations')
//left to run with these rules, the sketch will slowly 'evolve' with certain traits becoming more prevelent and 
//others dying out, though the mutations will keep it from becoming too mono-cultural.

//thanks to Dave Pagurek(@davepvm on Twitter) for his awesome library p5.Framebuffer (https://github.com/davepagurek/p5.Framebuffer)
//Which makes the depth of field blurs possible
//Also, if you really want to, any keystroke will toggle orbitControl() w the easyCam library(thanks again Dave!) and explore the little world



let bg
let eaters=[]
let colors=["#db5aba","#c455a8","#cf8ba3","#d7a6b3","#e5cdc8"]
let blurRenderer
let cam
let on

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	 blurRenderer = createBlurRenderer()
	blurRenderer.setIntensity(0.12)
	cam = createEasyCam()
	cam.auto_update = false
 noOf= (width+height)/4
	for(let i=0; i<noOf; i++){
		let coloring= floor(random(0, 5))
		eaters.push(new eater(random(-width/2, width/2), random(-height/2, height/2), random(-400, 200), random(5, 20), floor(random(3, 24)), floor(random(3, 24)), coloring))
	}
	on=false
}

function draw() {
	camera(0, 0, 600);

	noStroke()
	 blurRenderer.draw(() => {
		clear()
		 background('#F0EAD6')
		 if(on){
		 cam.update()
		 }

	ambientLight(255)
	directionalLight(250, 250, 250, 1, 1, -1); 

		 push()
		translate(0, 0, 30)
		blurRenderer.focusHere()
		pop()
	noStroke()

for(let i=eaters.length-1; i>=0; i--){
		if(frameCount>30){
		eaters[i].move();
		}
	  eaters[i].show();
	  eaters[i].full();
		eaters[i].eat();

	}
 }
)
}

class eater{

constructor(x, y, z, s, dx, dy, c){
	this.pos= createVector(x, y, z)
	this.vel= p5.Vector.random3D();
  this.color=c
	//this.color=random(20, 80)
	this.vel.setMag(2)
  this.s=s
	this.targetS=s
	this.detailX= dx
	this.detailY= dy
	this.rX=random(TWO_PI)
	this.rY=random(TWO_PI)
	this.rZ=random(TWO_PI)
	this.rxSpeed=random(-0.01, 0.01)
	this.rySpeed=random(-0.01, 0.01)
	this.rzSpeed=random(-0.01, 0.01)
  }

move(){
	let weight= this.s/500
	this.vel.setMag(1- weight)
	this.pos.add(this.vel)
	this.rX+=this.rxSpeed
	this.rY+=this.rySpeed
	this.rZ+=this.rzSpeed
	//edges
  if(this.pos.x < -width/2+2 || this.pos.x > width/2 -2){
		this.vel.mult(-1, 1, 0) 
	}
	 if(this.pos.y < -height/2+2 || this.pos.y > height/2 -2){
		this.vel.mult(1, -1,0) 
	}	

	 if(this.pos.z < -400 || this.pos.z > 200){
		this.vel.mult(1, 1, -1) 
	}	
}

eat(){
//if touches other eater, the bigger eater eats the smaller
	if(this.s<this.targetS){
		this.s+=1
	}
	let index = eaters.indexOf(this);

	for(let i=0; i<eaters.length; i++)
	{
	if(index!=i){
		let d=p5.Vector.dist(this.pos, eaters[i].pos)
			if(d< this.s/2+ eaters[i].s/2){
				//bigger one eats smaller one

				if(this.s > eaters[i].s){
					this.targetS+= eaters[i].s/2;
					eaters.splice(i, 1);
				} 

     }
	}
	}
}

full(){
	if(this.s>120){
		let divider= int(random(40,120))
		let pie= this.s *4
		while(pie>0){
			let piece= random(5, 10)
			pie-=piece
			let xdeter
			let ydeter
			let colorer
			let xdetChooser= random(100)
			let ydetChooser= random(100)
			let colorChooser= random(100)
			if(xdetChooser<97){
				xdeter=this.detailX
			} else{
				xdeter=floor(random(3, 24))
			}
			if(ydetChooser<97){
				ydeter=this.detailY
			} else{
				ydeter=floor(random(3, 24))
			}
			if(colorChooser<97){
				colorer=this.color
			}else{
				colorer=floor(random(0, 5))
			}

			let xey= constrain(this.pos.x+ random(-this.s/2, this.s/2), -width/2+3, width/2-3)
			let yey= constrain(this.pos.y+ random(-this.s/2, this.s/2), -height/2+3, height/2-3)
			let zey= constrain(this.pos.z+ random(-this.s/4, this.s/4), -397, 197)
			eaters.push(new eater(xey, yey, zey, piece, xdeter, ydeter, colorer))

		}

		var index = eaters.indexOf(this);
		 eaters.splice(index, 1);
	}
}

show(){
	fill(colors[this.color]);
	push()
	translate(this.pos.x, this.pos.y, this.pos.z)
	rotateX(this.rX)
	rotateY(this.rY)
	rotateZ(this.rZ)
	sphere(this.s, this.detailX, this.detailY)
	pop()
}

}

function keyPressed() {

	on=!on
}

